    // One row of the ISO 4217 table.
    struct iso4217_row {
        std::string_view code;        // the alphabetic code, three capitals
        std::string_view name;        // the currency's name as SIX publishes it
        std::uint16_t numeric;        // the numeric code
        std::int8_t scale;            // the minor units, or -1 where ISO gives none (N.A., and historic codes)
        std::string_view withdrawn;   // the withdrawal date as SIX gives it ("2025-03", "1989 to 1990"), empty if current
        std::span<const std::string_view> countries;   // alpha-2 of the countries using it (SIX list one), sorted
        std::string_view symbol;      // CLDR's root-locale symbol ("A$", "€"), or the code where CLDR gives none
        std::int8_t cash_scale;       // CLDR's cash digits, or -1 where CLDR gives no cash rule
        std::uint8_t cash_rounding;   // the cash increment in units of 10^-cash_scale (5 for CHF), 0 if none
    };

