    // One type per code. A type with scale() models snicholls::currency_like (and asset_like); the N.A. codes
    // (XAU, XAG, XPT, XPD, XDR, the funds) and historic ones have none: give one with snicholls::with_scale.
    // Each declares its presentation, found by ADL: a label, CLDR's root-locale symbol, and minor_units.
    /// \brief ISO 4217 ADP: Andorran Peseta, numeric 020, no ISO minor units, withdrawn 2003-07.
    struct ADP {
        /// \brief The alphabetic code.
        /// \return `"ADP"`.
        static constexpr std::string_view code() noexcept { return "ADP"; }
        /// \brief The currency's name, as SIX publishes it.
        /// \return The name.
        static constexpr std::string_view name() noexcept { return "Andorran Peseta"; }
        /// \brief The numeric code.
        /// \return 20.
        static constexpr std::uint16_t numeric() noexcept { return 20; }
        /// \brief When the code was withdrawn, as SIX's historic list gives it.
        /// \return The date.
        static constexpr std::string_view withdrawn() noexcept { return "2003-07"; }
        /// \brief Presentation, found by ADL: the label "ADP" (CLDR's root-locale symbol, or the code where CLDR gives none).
        /// \return The attribute set.
        friend constexpr auto attributes(const ADP&) noexcept { return ::snicholls::attrs(::snicholls::label{"ADP"}); }
    };
